// Aplana el desglose JSONB y adjunta datos del servicio original.
const d = $json.desglose;
if (!d || d.facturable === false) {
  return [{ json: { facturable: false, servicio_id: d ? d.servicio_id : null } }];
}
return [{ json: d }];

// Construye el payload CFDI 4.0 para Facturama a partir del desglose
// (nodo 'Preparar desglose') y los datos fiscales (nodo anterior).
const d = $('Preparar desglose').item.json;
const f = $json;

const concepto = {
  ProductCode: d.clave_prod_serv_sat,
  UnitCode: d.clave_unidad_sat,
  Unit: 'Servicio',
  Description: `Servicio ${d.tipo_servicio} · ${d.cantidad_unidades} unidad(es) ${d.tipo_unidad} · ${f.numero_contrato}${d.geocerca_nombre ? ' · ' + d.geocerca_nombre : ''}`,
  IdentificationNumber: d.servicio_id,
  Quantity: 1,
  UnitPrice: d.base_gravable,
  Subtotal: d.base_gravable,
  Discount: 0,
  TaxObject: '02',
  Taxes: [
    {
      Name: 'IVA',
      Rate: d.iva_tasa,
      Total: d.iva,
      Base: d.base_gravable,
      IsRetention: false,
      IsFederalTax: true
    }
  ],
  Total: d.total
};

const cfdi = {
  NameId: '1',
  CfdiType: 'I',
  ExpeditionPlace: '64000',
  PaymentForm: f.forma_pago || '03',
  PaymentMethod: f.metodo_pago || 'PUE',
  Currency: 'MXN',
  Receiver: {
    Rfc: f.rfc,
    Name: f.nombre_razon_social,
    CfdiUse: f.uso_cfdi || 'G03',
    FiscalRegime: f.regimen_fiscal,
    TaxZipCode: f.codigo_postal_fiscal
  },
  Items: [concepto]
};

return [{ json: { cfdi, desglose: d, fiscal: f } }];
